WITH customer_stats AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN status = 'RETURNED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_returned, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(channel))) AS channel_values FROM orders GROUP BY customer_id) SELECT c.credit_limit, c.signup_date, cs.pct_returned, cs.channel_values FROM customers c INNER JOIN customer_stats cs ON c.id = cs.customer_id WHERE cs.pct_returned >= 28 ORDER BY c.credit_limit DESC;
